import sys, random, itertools as it, inspect
sys.path.insert(0, sys.argv[1]); sys.path.insert(0, sys.argv[2])
import mi_old as A, more_itertools as B
random.seed(1)
def mat(x, d=0):
    if d>3: return x
    if isinstance(x,(str,bytes,int,float,bool,type(None))): return x
    if isinstance(x,dict): return {k:mat(v,d+1) for k,v in x.items()}
    try: return [mat(y,d+1) for y in it.islice(iter(x),200)]
    except TypeError: return x
def run(mod,name,args,kw):
    try: return ('ok', mat(getattr(mod,name)(*args,**kw)))
    except Exception as e: return ('err', type(e).__name__)
lists=lambda: [random.randint(0,4) for _ in range(random.randint(0,9))]
preds=[lambda x:x%2==0, lambda x:x>2]
cases={}
def add(n,*gens): cases.setdefault(n,[]).append(gens)
common=sorted(set(A.__all__)&set(B.__all__))
skip={'sample','random_product','random_permutation','random_combination','random_combination_with_replacement','time_limited','consumer','callback_iter','with_iter','loops','iterate','tabulate','repeatfunc','padnone','repeat_each','repeat_last','ncycles','count_cycle','iter_except','iter_suppress','serialize','synchronized','concurrent_tee','AbortThread','SequenceView','numeric_range','peekable','seekable','countable','run_length','bucket','islice_extended','side_effect','consume','doublestarmap','sieve','nth_prime','is_prime','factor','totient','polynomial_eval','polynomial_from_roots','polynomial_derivative','dft','idft','matmul','reshape','transpose','convolve','dotproduct','sum_of_squares','outer_product','multinomial','unzip','spy','tee','ichunked','zip_broadcast','strictly_n','map_reduce','join_mappings','duplicates_everseen','classify_unique','powerset_of_sets','unique_everseen'}
bad={}
for name in common:
    if name in skip: continue
    f=getattr(B,name)
    if not callable(f) or inspect.isclass(f) and name[0].isupper(): continue
    for t in range(150):
        L=lists(); M=lists(); n=random.randint(0,5); p=random.choice(preds)
        for args in [(L,),(L,n),(n,L),(p,L),(L,p),(L,M),(L,M,lists())]:
            ra=run(A,name,args,{}); rb=run(B,name,args,{})
            if ra!=rb:
                bad.setdefault(name,[]).append((args if not callable(args[0]) else ('pred',)+args[1:], ra, rb))
for k,v in bad.items():
    print(k, len(v)); 
    for e in v[:2]: print('   ', str(e)[:300])
print("checked", len([c for c in common if c not in skip]))
EOF
